# Derive transformations on demo 1 rectangle 9x10; compare 8 marker coords
src={(2,5),(3,3),(3,4),(3,5),(3,7),(4,3),(5,3),(5,4),(5,5),(5,6),(6,2),(6,6)}
out={(2,5),(3,2),(3,3),(4,3),(4,5),(4,6),(5,3),(5,5),(6,3),(6,4),(6,5),(7,2)}
H,W=9,10
transforms={
'id':lambda r,c:(r,c),
'cw':lambda r,c:(c,H-1-r),
'ccw':lambda r,c:(W-1-c,r),
'180':lambda r,c:(H-1-r,W-1-c),
'flipH':lambda r,c:(r,W-1-c),
'flipV':lambda r,c:(H-1-r,c),
'diag':lambda r,c:(c,r),
'anti':lambda r,c:(W-1-c,H-1-r),
}
for n,f in transforms.items():
 t={f(r,c) for r,c in src}
 print(n,len(t),len(out),t==out,'intersect',len(t&out))
